INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Starter Website', 'STARTER PRESENCE', '6,999', 'one-time', 'For small shops and solo businesses that need a simple website, fast.', '["Custom 1-page high-converting landing page","100% mobile & tablet responsive","Direct WhatsApp click-to-chat button","Fast 5-day delivery","Google Maps location setup","Domain & hosting setup guidance"]', 'Choose Starter Plan', 0, 1, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Starter Website');
INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Growth & Automation', 'GROWTH BUSINESS', '14,999', 'one-time', 'For clinics, coaching centres, salons and restaurants that want new enquiries every week.', '["Up to 5 custom high-conversion pages","Smart WhatsApp lead capture & auto-reply","Appointment / booking form","Local SEO & Google Business Profile setup","Super fast <1.5s loading speed","30 days free maintenance & updates","7-day launch guarantee"]', 'Get Growth Plan', 1, 2, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Growth & Automation');
INSERT INTO plans (name, badge, price, period, description, features, cta, popular, sort, published) SELECT 'Full Digital Suite', 'SCALE & DOMINATE', '24,999', 'one-time', 'Website, WhatsApp automation and ads — everything you need to grow in your area.', '["Complete custom multi-page website","Advanced multi-step WhatsApp chatbot","Meta (Facebook & Instagram) ads setup","Ad creatives & copywriting","Meta Pixel & Conversions API tracking","60 days VIP priority support","Monthly analytics & performance report"]', 'Scale With Full Suite', 0, 3, 1 WHERE NOT EXISTS (SELECT 1 FROM plans WHERE name = 'Full Digital Suite');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'How fast will my website be live?', 'Most projects go live **within 5 to 7 working days**. A simple 1-page Starter website can be ready in 3–4 days. Before going live, you’ll get a private preview link to check it on your own phone.', 1, 1, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How fast will my website be live?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do I need any technical knowledge?', 'Not at all. Domain guidance, hosting, SSL security, mobile optimisation, Google setup and testing — I handle everything. Just send your business details and photos on WhatsApp.', 1, 2, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do I need any technical knowledge?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do I need to buy a domain and hosting myself?', 'If you already have a domain, we connect that one. If not, I’ll guide you to buy one in your own name (usually ₹600–₹800 a year), so it always stays yours.', 0, 3, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do I need to buy a domain and hosting myself?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🚀 Getting Started', 'Do you work with businesses outside Purulia?', 'Yes. I’m based in Manbazar, Purulia, and work with businesses across West Bengal and all over India. Everything happens over WhatsApp, phone calls and screen-sharing.', 0, 4, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Do you work with businesses outside Purulia?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'What exactly is lead generation?', 'It’s a system that regularly brings people interested in your service to you — through ads, Google and your website — and captures their name, phone number and what they need, so you can turn them into customers.', 1, 5, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What exactly is lead generation?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'How does WhatsApp automation bring me more customers?', 'When someone taps your website or ad, WhatsApp opens with a ready-made message. An auto-reply instantly welcomes them with a menu (services, prices, booking, timings) and saves their details. You’ll never lose a customer just because you were busy.', 1, 6, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How does WhatsApp automation bring me more customers?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'Can I still chat normally with my customers?', 'Yes. The automation only handles the first greeting, the menu and lead capture. You or your staff can step into any chat and talk whenever you like.', 0, 7, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Can I still chat normally with my customers?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🎯 Lead Generation & WhatsApp', 'Where do my leads go?', 'Every lead is automatically saved to a private Google Sheet — with name, phone, what they need and where they came from. So you can follow up and see what’s working.', 0, 8, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Where do my leads go?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '📣 Meta Ads (Facebook & Instagram)', 'How much should I spend on ads?', 'For a local business targeting a 5–15 km radius, **₹200 to ₹400 a day** is usually enough to start getting regular enquiries. We start small, measure, then scale what works.', 0, 9, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'How much should I spend on ads?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '📣 Meta Ads (Facebook & Instagram)', 'Is the ad budget included in your price?', 'No — ad spend is paid directly to Meta from your own account, so you stay in control. Our fee covers setup, creatives, ad copy, targeting and tracking.', 0, 10, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Is the ad budget included in your price?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'What are your payment terms?', '50% advance to start work, and the remaining 50% before launch, only after you’ve seen and approved the design. We accept UPI and bank transfer.', 0, 11, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What are your payment terms?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Are there hidden monthly fees?', 'No. The core packages are one-time payments. Monthly services like ad management or maintenance are completely optional — only if you want them.', 0, 12, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Are there hidden monthly fees?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Is the ad budget included in the Full Digital Suite?', 'The Suite covers setup, design, copy and tracking. Ad spend goes directly to Meta from your own account, so you stay in control. Most local businesses start with ₹200–₹400 a day.', 0, 13, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Is the ad budget included in the Full Digital Suite?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '💳 Pricing & Payments', 'Can I upgrade later?', 'Yes. You can start with Starter and move up to Growth or Full Suite later — you only pay the difference for the new work.', 0, 14, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Can I upgrade later?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🛠️ After Launch', 'What if I need changes later?', 'Every package includes free support after launch (30–60 days, depending on the plan). Price changes, new photos, Puja or festival offer banners — just send a WhatsApp message.', 0, 15, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'What if I need changes later?');
INSERT INTO faqs (category, question, answer, show_on_home, sort, published) SELECT '🛠️ After Launch', 'Will my website show up on Google?', 'Yes. Every site is built SEO-ready, submitted to Google Search Console and connected to your Google Business Profile, so nearby customers can find you.', 0, 16, 1 WHERE NOT EXISTS (SELECT 1 FROM faqs WHERE question = 'Will my website show up on Google?');
